/* Global Warming Explorer: service worker (generated by build.py; do not edit sw.js).
   Strategy
   - Install: precache the app shell. The new worker WAITS; the page shows an
     "Update available" toast and the visitor chooses when to refresh, so nobody
     is ever stuck on a half-updated site.
   - Static assets (CSS, JS, fonts, icons, images): cache-first (they are versioned by the build).
   - Pages: stale-while-revalidate, with the offline page as the last fallback.
   - Live data (Open-Meteo, global-warming.org): network only, never cached,
     so numbers are never stale. The widgets show their own "offline" state.
   - Old caches are deleted on activate. */
"use strict";

const CACHE_VERSION = "gw-explorer-__BUILD_ID__";
const APP_SHELL = __APP_SHELL__;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_VERSION).then((cache) =>
      Promise.all(APP_SHELL.map((url) => cache.add(url).catch(() => {})))
    )
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((names) => Promise.all(names.filter((n) => n !== CACHE_VERSION).map((n) => caches.delete(n))))
      .then(() => self.clients.claim())
  );
});

function isStatic(url) {
  return /\.(?:css|js|woff2|png|jpg|jpeg|webp|avif|svg|ico|pdf)$/i.test(url.pathname);
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // live data and external hosts: network only

  if (req.mode === "navigate") {
    event.respondWith(
      caches.match(req, { ignoreSearch: true }).then((cached) => {
        const network = fetch(req)
          .then((res) => {
            if (res && res.ok) {
              const copy = res.clone();
              caches.open(CACHE_VERSION).then((c) => c.put(req, copy));
            }
            return res;
          })
          .catch(() => null);
        if (cached) { event.waitUntil(network); return cached; }
        return network.then((res) => res || caches.match("offline.html"));
      })
    );
    return;
  }

  if (isStatic(url)) {
    event.respondWith(
      caches.match(req).then((cached) =>
        cached ||
        fetch(req).then((res) => {
          if (res && res.ok) {
            const copy = res.clone();
            caches.open(CACHE_VERSION).then((c) => c.put(req, copy));
          }
          return res;
        })
      )
    );
  }
});
